/**
 * Thread pool implementation with TTL-based result caching.
 *
 * Manages a pool of worker threads for parallel task execution.
 * Completed task results are cached with a configurable TTL to avoid
 * redundant computation.
 */

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

// ---------------------------------------------------------------------------
// Worker script (executed in a worker thread)
// ---------------------------------------------------------------------------

const WORKER_SCRIPT = `
const { parentPort, workerData } = require('worker_threads');
parentPort.on('message', ({ taskId, fnString, args }) => {
  try {
    const fn = new Function('return (' + fnString + ')')();
    const result = fn(...args);
    if (result && typeof result.then === 'function') {
      result.then(
        (val) => parentPort.postMessage({ taskId, result: val }),
        (err) => parentPort.postMessage({ taskId, error: err.message })
      );
    } else {
      parentPort.postMessage({ taskId, result });
    }
  } catch (err) {
    parentPort.postMessage({ taskId, error: err.message });
  }
});
`;

// ---------------------------------------------------------------------------
// cache_with_ttl  –  Thread Pool with TTL result cache
// ---------------------------------------------------------------------------

/**
 * Create a thread pool that caches task results with a time-to-live.
 *
 * @param {object}   opts
 * @param {number}   opts.poolSize        - Number of worker threads (default 4)
 * @param {number}   opts.ttlMs           - Cache TTL in milliseconds (default 60 000)
 * @param {number}   opts.maxCacheSize    - Max cached entries before eviction (default 1000)
 * @returns {ThreadPool}
 */
function cache_with_ttl({ poolSize = 4, ttlMs = 60000, maxCacheSize = 1000 } = {}) {
  return new ThreadPool({ poolSize, ttlMs, maxCacheSize });
}

// ---------------------------------------------------------------------------
// ThreadPool class
// ---------------------------------------------------------------------------

class ThreadPool {
  constructor({ poolSize, ttlMs, maxCacheSize }) {
    this._poolSize = Math.max(1, poolSize);
    this._ttlMs = ttlMs;
    this._maxCacheSize = maxCacheSize;
    this._workers = [];
    this._idleWorkers = [];
    this._taskQueue = [];
    this._pending = new Map();        // taskId -> { resolve, reject }
    this._cache = new Map();          // cacheKey -> { value, timestamp }
    this._nextTaskId = 0;
    this._shutdown = false;
    this._activeTaskCount = 0;

    this._initWorkers();
  }

  // ── Worker lifecycle ──────────────────────────────────────────────────

  _initWorkers() {
    for (let i = 0; i < this._poolSize; i++) {
      const w = this._createWorker();
      this._workers.push(w);
      this._idleWorkers.push(w);
    }
  }

  _createWorker() {
    const w = new Worker(WORKER_SCRIPT, { eval: true });
    w.on('message', (msg) => this._onWorkerMessage(w, msg));
    w.on('error', (err) => this._onWorkerError(w, err));
    w._busy = false;
    return w;
  }

  _onWorkerMessage(worker, { taskId, result, error }) {
    const entry = this._pending.get(taskId);
    if (entry) {
      this._pending.delete(taskId);
      if (error) {
        entry.reject(new Error(error));
      } else {
        // Cache the result
        this._cache.set(entry.cacheKey, { value: result, timestamp: Date.now() });
        this._evictIfNeeded();
        entry.resolve(result);
      }
    }
    this._activeTaskCount--;
    worker._busy = false;
    this._idleWorkers.push(worker);
    this._drainQueue();
  }

  _onWorkerError(worker, err) {
    // Replace the crashed worker
    const idx = this._workers.indexOf(worker);
    if (idx !== -1) {
      this._workers[idx] = this._createWorker();
      this._idleWorkers.push(this._workers[idx]);
    }
    const idleIdx = this._idleWorkers.indexOf(worker);
    if (idleIdx !== -1) this._idleWorkers.splice(idleIdx, 1);
  }

  // ── Cache helpers ─────────────────────────────────────────────────────

  _cacheKey(fn, args) {
    return JSON.stringify({ fn: fn.toString(), args });
  }

  _getCached(key) {
    const entry = this._cache.get(key);
    if (!entry) return undefined;
    if (Date.now() - entry.timestamp > this._ttlMs) {
      this._cache.delete(key);
      return undefined;
    }
    return entry.value;
  }

  _evictIfNeeded() {
    // Remove expired entries
    const now = Date.now();
    for (const [key, entry] of this._cache) {
      if (now - entry.timestamp > this._ttlMs) {
        this._cache.delete(key);
      }
    }
    // Evict oldest if still over limit
    while (this._cache.size > this._maxCacheSize) {
      const oldest = this._cache.keys().next().value;
      this._cache.delete(oldest);
    }
  }

  // ── Task queue ────────────────────────────────────────────────────────

  _drainQueue() {
    while (this._taskQueue.length > 0 && this._idleWorkers.length > 0) {
      const task = this._taskQueue.shift();
      const worker = this._idleWorkers.pop();
      worker._busy = true;
      worker._currentTaskId = task.taskId;
      worker.postMessage({
        taskId: task.taskId,
        fnString: task.fnString,
        args: task.args,
      });
    }
  }

  // ── Public API ────────────────────────────────────────────────────────

  /**
   * Submit a task for parallel execution.
   *
   * @param {Function} fn    - Pure function to execute (will be serialized)
   * @param {Array}    args  - Arguments to pass to fn
   * @returns {Promise<*>}   Resolves with the task result (from cache or worker)
   */
  run(fn, ...args) {
    if (this._shutdown) return Promise.reject(new Error('Pool is shut down'));

    const cacheKey = this._cacheKey(fn, args);
    const cached = this._getCached(cacheKey);
    if (cached !== undefined) return Promise.resolve(cached);

    const taskId = this._nextTaskId++;
    return new Promise((resolve, reject) => {
      this._pending.set(taskId, { resolve, reject, cacheKey });
      this._activeTaskCount++;
      this._taskQueue.push({
        taskId,
        fnString: fn.toString(),
        args,
      });
      this._drainQueue();
    });
  }

  /**
   * Run multiple tasks in parallel and return all results.
   * @param {Array<{fn: Function, args: Array}>} tasks
   * @returns {Promise<Array>}
   */
  runAll(tasks) {
    return Promise.all(tasks.map((t) => this.run(t.fn, ...t.args)));
  }

  /** Number of cached results. */
  get cacheSize() {
    return this._cache.size;
  }

  /** Number of tasks currently executing. */
  get activeTasks() {
    return this._activeTaskCount;
  }

  /** Number of tasks waiting in the queue. */
  get queuedTasks() {
    return this._taskQueue.length;
  }

  /** Clear the result cache. */
  clearCache() {
    this._cache.clear();
  }

  /** Gracefully shut down all workers. */
  async shutdown() {
    this._shutdown = true;
    // Reject queued tasks
    for (const task of this._taskQueue) {
      const entry = this._pending.get(task.taskId);
      if (entry) {
        entry.reject(new Error('Pool shut down before task could run'));
        this._pending.delete(task.taskId);
      }
    }
    this._taskQueue = [];
    // Terminate workers
    await Promise.all(this._workers.map((w) => w.terminate()));
    this._workers = [];
    this._idleWorkers = [];
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

function runTests() {
  let passed = 0;
  let failed = 0;
  const failures = [];

  function assert(cond, desc) {
    if (cond) { passed++; console.log(`  PASS  ${desc}`); }
    else { failed++; failures.push(desc); console.error(`  FAIL  ${desc}`); }
  }

  async function assertThrowsAsync(fn, desc) {
    try { await fn(); failed++; failures.push(desc); console.error(`  FAIL  ${desc} (no error)`); }
    catch { passed++; console.log(`  PASS  ${desc}`); }
  }

  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

  // Helper: simple pure functions for testing
  const add = (a, b) => a + b;
  const square = (x) => x * x;
  const slowDouble = (x) => { /* simulate work */ return x * 2; };
  const throwIfNegative = (x) => { if (x < 0) throw new Error('negative'); return x; };

  // ── Run all tests ─────────────────────────────────────────────────────

  (async () => {

    // ===== Basic execution ================================================

    console.log('\n=== Basic execution ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      const result = await pool.run(add, 3, 4);
      assert(result === 7, 'add(3,4) = 7');
      await pool.shutdown();
    }

    // ===== Parallel execution =============================================

    console.log('\n=== Parallel execution ===');
    {
      const pool = cache_with_ttl({ poolSize: 4, ttlMs: 5000 });
      const results = await pool.runAll([
        { fn: square, args: [2] },
        { fn: square, args: [3] },
        { fn: square, args: [4] },
        { fn: square, args: [5] },
      ]);
      assert(results[0] === 4, 'square(2)=4');
      assert(results[1] === 9, 'square(3)=9');
      assert(results[2] === 16, 'square(4)=16');
      assert(results[3] === 25, 'square(5)=25');
      await pool.shutdown();
    }

    // ===== Caching ========================================================

    console.log('\n=== Caching (same args return cached) ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      const r1 = await pool.run(add, 10, 20);
      assert(r1 === 30, 'first call returns 30');
      assert(pool.cacheSize === 1, 'cache size = 1 after first call');
      const r2 = await pool.run(add, 10, 20);
      assert(r2 === 30, 'cached call also returns 30');
      assert(pool.cacheSize === 1, 'cache size still 1 (no duplicate)');
      await pool.shutdown();
    }

    // ===== TTL expiry =====================================================

    console.log('\n=== TTL expiry ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 100 });
      await pool.run(add, 1, 2);
      assert(pool.cacheSize === 1, 'entry cached');
      await sleep(150);
      const r = await pool.run(add, 1, 2);
      assert(r === 3, 'correct result after TTL expiry');
      // After expiry + re-fetch, it should be cached again
      assert(pool.cacheSize === 1, 're-cached after expiry');
      await pool.shutdown();
    }

    // ===== Max cache size eviction =========================================

    console.log('\n=== Max cache size eviction ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 10000, maxCacheSize: 3 });
      await pool.run(add, 1, 0);
      await pool.run(add, 2, 0);
      await pool.run(add, 3, 0);
      assert(pool.cacheSize === 3, 'cache at max 3');
      await pool.run(add, 4, 0);
      assert(pool.cacheSize === 3, 'eviction keeps size at 3');
      await pool.shutdown();
    }

    // ===== Task count properties ==========================================

    console.log('\n=== Task count properties ===');
    {
      const pool = cache_with_ttl({ poolSize: 1, ttlMs: 5000 });
      assert(pool.activeTasks === 0, 'no active tasks initially');
      assert(pool.queuedTasks === 0, 'no queued tasks initially');
      const p = pool.run(add, 1, 1);
      // Task may complete instantly or be active briefly
      await p;
      assert(pool.activeTasks === 0, 'no active tasks after completion');
      await pool.shutdown();
    }

    // ===== Queue overflow (more tasks than workers) ========================

    console.log('\n=== Queue overflow ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      const promises = [];
      for (let i = 0; i < 6; i++) {
        promises.push(pool.run(square, i));
      }
      const results = await Promise.all(promises);
      assert(results.join(',') === '0,1,4,9,16,25', '6 tasks queued on 2 workers all correct');
      await pool.shutdown();
    }

    // ===== Error propagation ==============================================

    console.log('\n=== Error propagation ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      await assertThrowsAsync(
        () => pool.run(throwIfNegative, -1),
        'throws on negative input'
      );
      // Pool should still work after an error
      const r = await pool.run(add, 5, 5);
      assert(r === 10, 'pool recovers after error');
      await pool.shutdown();
    }

    // ===== Shutdown rejects new tasks =====================================

    console.log('\n=== Shutdown behaviour ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      await pool.run(add, 1, 1); // ensure pool is alive
      await pool.shutdown();
      await assertThrowsAsync(
        () => pool.run(add, 1, 1),
        'run() after shutdown throws'
      );
    }

    // ===== clearCache ====================================================

    console.log('\n=== clearCache ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      await pool.run(add, 7, 8);
      assert(pool.cacheSize === 1, 'cache populated');
      pool.clearCache();
      assert(pool.cacheSize === 0, 'cache cleared');
      await pool.shutdown();
    }

    // ===== Multiple arg types =============================================

    console.log('\n=== Multiple argument types ===');
    {
      const pool = cache_with_ttl({ poolSize: 2, ttlMs: 5000 });
      const concat = (a, b) => `${a}-${b}`;
      const r = await pool.concat('hello', 'world');
      // Use run instead
      const r2 = await pool.run(concat, 'hello', 'world');
      assert(r2 === 'hello-world', 'string args work');

      const objArg = (o) => o.x + o.y;
      const r3 = await pool.run(objArg, { x: 10, y: 20 });
      assert(r3 === 30, 'object args work');

      const arrArg = (a) => a.reduce((s, v) => s + v, 0);
      const r4 = await pool.run(arrArg, [1, 2, 3, 4]);
      assert(r4 === 10, 'array args work');
      await pool.shutdown();
    }

    // ===== Large parallel burst ============================================

    console.log('\n=== Large parallel burst (50 tasks, 4 workers) ===');
    {
      const pool = cache_with_ttl({ poolSize: 4, ttlMs: 10000 });
      const tasks = [];
      for (let i = 0; i < 50; i++) {
        tasks.push({ fn: square, args: [i] });
      }
      const results = await pool.runAll(tasks);
      let allCorrect = true;
      for (let i = 0; i < 50; i++) {
        if (results[i] !== i * i) { allCorrect = false; break; }
      }
      assert(allCorrect, 'all 50 parallel tasks returned correct results');
      assert(pool.cacheSize === 50, 'all 50 results cached');
      await pool.shutdown();
    }

    // ===== Default pool size ==============================================

    console.log('\n=== Default pool size ===');
    {
      const pool = cache_with_ttl(); // defaults
      const r = await pool.run(add, 100, 200);
      assert(r === 300, 'default pool works');
      await pool.shutdown();
    }

    // ===== Cache isolation per pool ========================================

    console.log('\n=== Cache isolation per pool ===');
    {
      const pool1 = cache_with_ttl({ poolSize: 1, ttlMs: 5000 });
      const pool2 = cache_with_ttl({ poolSize: 1, ttlMs: 5000 });
      await pool1.run(add, 1, 1);
      assert(pool1.cacheSize === 1, 'pool1 cached');
      assert(pool2.cacheSize === 0, 'pool2 unaffected');
      await pool1.shutdown();
      await pool2.shutdown();
    }

    // ── Summary ──────────────────────────────────────────────────────────

    console.log(`\n${'='.repeat(50)}`);
    console.log(`Results: ${passed} passed, ${failed} failed, ${passed + failed} total`);
    if (failures.length > 0) {
      console.log('\nFailed tests:');
      failures.forEach((f) => console.log(`  - ${f}`));
    }
    if (failed > 0) process.exit(1);

  })().catch((err) => {
    console.error('Unhandled test error:', err);
    process.exit(1);
  });
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { cache_with_ttl, ThreadPool };
  if (require.main === module) runTests();
} else {
  runTests();
}

